import { createInsertSchema } from 'drizzle-zod';
import { pgTable, text, serial, timestamp, numeric, boolean, integer } from 'drizzle-orm/pg-core';
import { z } from 'zod/v4';

// 👤 User accounts. Auth fields are nullable so existing users remain valid
// until they register credentials through the auth route.
export const users = pgTable('users', {
  id: serial('id').primaryKey(),
  fullName: text('full_name').notNull(),
  email: text('email').unique(),
  password: text('password'),
  phone: text('phone').notNull().unique(),
  address: text('address'),
  role: text('role').default('buyer'),
  shopName: text('shop_name'),
  createdAt: timestamp('created_at').defaultNow(),
});

export const bankAccountsTable = pgTable('bank_accounts', {
  id: serial('id').primaryKey(),
  bankName: text('bank_name').notNull(),
  accountName: text('account_name').notNull(),
  accountNumber: text('account_number').notNull(),
  isActive: boolean('is_active').notNull().default(true),
  createdAt: timestamp('created_at').notNull().defaultNow(),
});

export const insertBankAccountSchema = createInsertSchema(bankAccountsTable).omit({
  id: true,
  isActive: true,
  createdAt: true,
});

export type BankAccount = typeof bankAccountsTable.$inferSelect;
export type InsertBankAccount = z.infer<typeof insertBankAccountSchema>;

// 🏪 1. የሱቆች ሰንጠረዥ (Shops Table)
export const shops = pgTable('shops', {
  id: serial('id').primaryKey(),
  fullName: text('full_name').notNull(),
  phone: text('phone').notNull().unique(),
  faydaNo: text('fayda_no').notNull(),
  tinNo: text('tin_no'),
  address: text('address').notNull(),
  shopType: text('shop_type').notNull(),
  shopDesc: text('shop_desc'),
  accountNumber: text('account_number').notNull(),
  bannerUri: text('banner_uri').default('https://picsum.photos/seed/shopbanner/800/300'),
  profileUri: text('profile_uri').default('https://picsum.photos/seed/useravatar/200/200'),
  createdAt: timestamp('created_at').defaultNow(),
});

// 📦 2. የእቃዎች ሰንጠረዥ (Products Table)
export const products = pgTable('products', {
  id: serial('id').primaryKey(),
  title: text('title').notNull(),
  price: numeric('price').notNull(),
  category: text('category').default('የቤት እቃዎች'),
  description: text('description'),
  photoUri: text('photo_uri').notNull(),
  videoUri: text('video_uri'),
  sellerPhone: text('seller_phone').notNull(),
  isFavorite: boolean('is_favorite').default(false),
  rating: numeric('rating').default('5.0'),
  reviewsCount: serial('reviews_count'),
  createdAt: timestamp('created_at').defaultNow(),
});

// 💳 3. የትዕዛዞች እና Escrow ሰንጠረዥ (Orders Table)
export const orders = pgTable('orders', {
  id: serial('id').primaryKey(),
  productId: serial('product_id').references(() => products.id),
  amount: numeric('amount').notNull(),
  paymentMethod: text('payment_method').notNull(),
  deliveryTime: text('delivery_time').notNull(),
  deliveryNote: text('delivery_note'),
  otpCode: text('otp_code').notNull(),
  status: text('status').default('PENDING_ESCROW'),
  createdAt: timestamp('created_at').defaultNow(),
});

export const transactions = pgTable('transactions', {
  id: serial('id').primaryKey(),
  txRef: text('tx_ref').notNull().unique(),
  buyerId: integer('buyer_id').references(() => users.id),
  productId: integer('product_id').references(() => products.id),
  amount: numeric('amount').notNull(),
  status: text('status').default('PENDING'),
  otpCode: text('otp_code').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
});

export const messages = pgTable('messages', {
  id: serial('id').primaryKey(),
  senderId: integer('sender_id').notNull().references(() => users.id),
  receiverId: integer('receiver_id').notNull().references(() => users.id),
  message: text('message').notNull(),
  createdAt: timestamp('created_at').defaultNow(),
});

